1	package main
2	
3	import (
4		"os"
5		"os/exec"
6		"path/filepath"
7		"strings"
8		"sync"
9		"testing"
10	)
11	
12	// buildZkcircuit builds the CLI binary into a temp file for subprocess tests.
13	func buildZkcircuit(t *testing.T) string {
14		t.Helper()
15		bin := filepath.Join(t.TempDir(), "zkcircuit")
16		cmd := exec.Command("go", "build", "-o", bin, ".")
17		if out, err := cmd.CombinedOutput(); err != nil {
18			t.Fatalf("build zkcircuit: %v\n%s", err, out)
19		}
20		return bin
21	}
22	
23	func runBin(t *testing.T, bin, dir string, args ...string) (int, string, string) {
24		t.Helper()
25		// args[0] is the command; --dir is inserted after it.
26		cmdArgs := append([]string{args[0], "--dir", dir}, args[1:]...)
27		cmd := exec.Command(bin, cmdArgs...)
28		var outBuf, errBuf strings.Builder
29		cmd.Stdout = &outBuf
30		cmd.Stderr = &errBuf
31		err := cmd.Run()
32		code := 0
33		if err != nil {
34			if ee, ok := err.(*exec.ExitError); ok {
35				code = ee.ExitCode()
36			} else {
37				t.Fatalf("run %v: %v", args, err)
38			}
39		}
40		return code, outBuf.String(), errBuf.String()
41	}
42	
43	func TestCLICircuitUpdatePartial(t *testing.T) {
44		dir := filepath.Join(t.TempDir(), "bench")
45		type res struct {
46			code int
47			out  string
48			err  string
49		}
50		call := func(args ...string) res {
51			c, o, e := runCapture(t, args...)
52			return res{c, o, e}
53		}
54	
55		// Seed the exact fixture: 2 constraints, 1 public, 3 private, "初稿".
56		if r := call("circuit-create", "--dir", dir, "--name", "c", "--version", "1",
57			"--constraints", "2", "--public-inputs", "1", "--private-inputs", "3",
58			"--description", "初稿"); r.code != 0 {
59			t.Fatalf("create: %+v", r)
60		}
61	
62		// Description-only update must leave all three counts intact.
63		r := call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
64			"--description", "改后")
65		if r.code != 0 {
66			t.Fatalf("description-only update: %+v", r)
67		}
68		if !strings.Contains(r.out, "constraints=2") || !strings.Contains(r.out, "public_inputs=1") ||
69			!strings.Contains(r.out, "private_inputs=3") || !strings.Contains(r.out, `description="改后"`) {
70			t.Fatalf("description-only update changed fields: %q", r.out)
71		}
72	
73		// Explicit zero input counts must zero them, not be treated as omitted.
74		r = call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
75			"--public-inputs", "0", "--private-inputs", "0")
76		if r.code != 0 || !strings.Contains(r.out, "public_inputs=0") || !strings.Contains(r.out, "private_inputs=0") {
77			t.Fatalf("explicit zero counts: %+v", r)
78		}
79		// Constraints and description untouched.
80		if !strings.Contains(r.out, "constraints=2") || !strings.Contains(r.out, `description="改后"`) {
81			t.Fatalf("zero update leaked: %q", r.out)
82		}
83	
84		// Explicit empty description must clear it.
85		r = call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
86			"--description", "")
87		if r.code != 0 || !strings.Contains(r.out, `description=""`) {
88			t.Fatalf("explicit empty description: %+v", r)
89		}
90		if !strings.Contains(r.out, "constraints=2") || !strings.Contains(r.out, "public_inputs=0") ||
91			!strings.Contains(r.out, "private_inputs=0") {
92			t.Fatalf("empty description update leaked: %q", r.out)
93		}
94	
95		// No modifiable fields: success, full record, nothing written.
