242				fmt.Fprintf(os.Stderr, "helper create: %v\n", err)
243				out.Flush()
244				os.Exit(11)
245			}
246			if _, err := s.FreezeCircuit(prefix, v); err != nil {
247				fmt.Fprintf(os.Stderr, "helper freeze: %v\n", err)
248				out.Flush()
249				os.Exit(12)
250			}
