	s := openTestStore(t)
	// Definition with a distinctive constraint order.
	ordered := `{"modulus":"7","constraints":[
		{"a":[{"wire":1,"coeff":"3"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"2"}]},
		{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"5"}]},
		{"a":[],"b":[],"c":[]}]}`
